// build-widgets.mjs — embed every widget in its area MOC.
//
// The MOC skeleton contains a marker comment (`<!-- generated by build-widgets.mjs -->`)
// under its "## Widgets" heading. This script replaces everything from that heading to
// the next heading with a generated list, so widget embeds never drift from the files.
//
//   node build/build-widgets.mjs                  # every area
//   node build/build-widgets.mjs --area <Area>    # one area (accepts "05_Electromagnetics"
//                                                 # or "Electromagnetics")

import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, basename, relative } from 'node:path';
import { VAULT, AREAS } from './vault.mjs';
import { WIDGET_EMBED_SIZE } from './widget-map.mjs';

const MARKER = '<!-- generated by build-widgets.mjs -->';

// The embed size itself lives in widget-map.mjs, because expand.mjs emits the same embeds
// inside the topic notes. One definition, or the MOC and the notes drift apart.
const EMBED_SIZE = WIDGET_EMBED_SIZE;

// `--area <AreaName>` scopes the run to one MOC, so a change to the emitted markup can
// be validated on a single area before it is applied to all 31.
const argv = process.argv.slice(2);
const areaArg = argv.indexOf('--area');
const onlyArea = areaArg >= 0 ? argv[areaArg + 1] : null;

function walkDirs(dir, out = []) {
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) {
      out.push(p);
      walkDirs(p, out);
    }
  }
  return out;
}

// Map area folder -> widgets on disk
const widgetDirs = walkDirs(VAULT).filter((p) => basename(p) === 'Widgets');

let updated = 0;
let totalWidgets = 0;
const report = [];

for (const dir of widgetDirs) {
  const areaDir = dir.slice(0, dir.lastIndexOf('Widgets')).replace(/[\\/]+$/, '');
  const areaName = basename(areaDir);
  const area = AREAS.find((a) => a.area === areaName);
  if (!area) continue;
  if (onlyArea && area.area !== onlyArea && area.area.replace(/^\d+_/, '') !== onlyArea) continue;

  const mocs = readdirSync(areaDir).filter((f) => f.startsWith('_MOC_') && f.endsWith('.md'));
  if (!mocs.length) continue;
  const mocFile = join(areaDir, mocs[0]);

  const widgets = readdirSync(dir)
    .filter((f) => f.toLowerCase().endsWith('.html'))
    .sort();

  totalWidgets += widgets.length;

  const body = widgets.length
    ? widgets
        .map((f) => {
          const base = f.replace(/\.html$/i, '');
          const label = base.replace(/_/g, ' ');
          // NOT a plain link. `.html` is not an accepted linkable format in Obsidian,
          // so `[[Name]]` never resolves and reads as a dead link (see check-links.mjs).
          // An EMBED of the real filename resolves through the "Embed HTML" plugin,
          // which renders the file as a live page — that is what lets the widget's
          // module script and its `../../../Assets/vault.js` import actually run.
          // The bold label keeps the widget named if the plugin is not installed.
          return `**${label}**\n\n![[${f}|${EMBED_SIZE}]]`;
        })
        .join('\n\n')
    : '_None yet._';

  let text = readFileSync(mocFile, 'utf8');
  if (!text.includes('## Widgets')) {
    text = text.trimEnd() + `\n\n## Widgets\n\n${MARKER}\n`;
  }

  // Replace from "## Widgets" up to the next "## " heading (or end).
  const re = /## Widgets[^\n]*\n([\s\S]*?)(?=\n## |\n*$)/;
  if (!re.test(text)) {
    console.log(`x could not find Widgets section in ${relative('.', mocFile)}`);
    continue;
  }
  const replacement = `## Widgets\n\n${MARKER}\n\n${body}\n`;
  const next = text.replace(re, replacement);
  if (next !== text) {
    writeFileSync(mocFile, next, 'utf8');
    updated++;
  }
  report.push({ area: areaName, widgets: widgets.length });
}

// A `--area` that matches nothing must fail loudly: a silent no-op looks like success.
if (onlyArea && !report.length) {
  console.error(`x no area matched --area ${onlyArea}`);
  console.error(`  valid areas: ${AREAS.map((a) => a.area).join(', ')}`);
  process.exitCode = 1;
}

console.log(`areas with widget folders: ${report.length}`);
console.log(`MOCs updated:              ${updated}`);
console.log(`widgets linked:            ${totalWidgets}`);
for (const r of report.filter((r) => r.widgets > 0)) {
  console.log(`  ${r.area}: ${r.widgets}`);
}
